(()=>{
  'use strict';
  const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const SESSION_SIZE=10;
  const state={questions:[],index:0,answers:[],client:null,live:false,userId:'',busy:false};
  const screens={landing:$('#landing'),game:$('#game'),summary:$('#summary')};
  const ids=['category','counter','gameProgress','benefitText','consequenceText','choices','resultPanel','resultKicker','resultTitle','totalVotes','pressPercent','walkPercent','pressBar','walkBar','positionText','scoreText','neutralNote','errorCard'].reduce((o,k)=>(o[k]=$(`#${k}`),o),{});

  function anonymousId(){let id=localStorage.getItem('the_button_anonymous_id');if(!id){id=`anon_${crypto.randomUUID()}`;localStorage.setItem('the_button_anonymous_id',id)}return id}
  function show(name){Object.values(screens).forEach(s=>s.classList.remove('is-active'));screens[name].classList.add('is-active');window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
  function shuffled(input){const a=[...input];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
  function variedSelection(bank){const groups={};shuffled(bank.filter(q=>q.active!==false)).forEach(q=>(groups[q.category]??=[]).push(q));const categories=shuffled(Object.keys(groups));const pick=[];while(pick.length<SESSION_SIZE&&categories.some(c=>groups[c].length)){for(const c of categories){if(groups[c].length&&pick.length<SESSION_SIZE)pick.push(groups[c].pop())}}return shuffled(pick)}
  function controversy(p){return Math.max(0,Math.round(100-2*Math.abs(p-50)))}
  function controversyLabel(score){if(score>=90)return'EXTREMELY DIVISIVE';if(score>=80)return'HIGHLY DIVISIVE';if(score>=70)return'DIVISIVE';if(score>=50)return'ONE-SIDED';return'VERY ONE-SIDED'}
  function demoResult(q,choice){const existing=JSON.parse(localStorage.getItem('the_button_demo_votes')||'{}');if(existing[q.id])return existing[q.id];const base=44+((q.id*17)%13);const total=280+((q.id*137)%2100);let press=Math.round(total*base/100);let walk=total-press;if(choice==='PRESS')press++;else walk++;const result={press_votes:press,walk_votes:walk,total_votes:press+walk,previous_choice:null,test_data:true};existing[q.id]=result;localStorage.setItem('the_button_demo_votes',JSON.stringify(existing));return result}
  async function initData(){state.userId=anonymousId();const cfg=window.BUTTON_CONFIG||{};if(cfg.SUPABASE_URL&&cfg.SUPABASE_ANON_KEY&&window.supabase){try{state.client=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY);const {data,error}=await state.client.rpc('get_game_questions',{question_count:SESSION_SIZE});if(error||!data?.length)throw error||new Error('No questions');state.questions=data;state.live=true;const pill=$('#modePill');pill.classList.add('is-live');pill.innerHTML='<span></span>LIVE · REAL RESULTS';return}catch(e){console.error('Supabase unavailable, using demo mode',e)}}state.questions=variedSelection(window.QUESTION_BANK)}
  async function start(){if(state.busy)return;state.busy=true;ids.errorCard.classList.remove('is-visible');try{await initData();state.index=0;state.answers=[];renderQuestion();show('game')}catch(e){console.error(e);ids.errorCard.classList.add('is-visible');show('game')}finally{state.busy=false}}
  function renderQuestion(){const q=state.questions[state.index];if(!q)return finish();ids.category.textContent=q.category;ids.counter.textContent=`QUESTION ${state.index+1} / ${SESSION_SIZE}`;ids.gameProgress.style.width=`${(state.index+1)*10}%`;ids.benefitText.textContent=q.benefit_text;ids.consequenceText.textContent=q.consequence_text;ids.resultPanel.classList.remove('is-visible');ids.choices.classList.remove('is-locked');$$('[data-choice]').forEach(b=>{b.disabled=false;b.classList.remove('is-pressed')});ids.errorCard.classList.remove('is-visible')}
  async function castVote(choice,button){if(state.busy)return;state.busy=true;button.classList.add('is-pressed');ids.choices.classList.add('is-locked');$$('[data-choice]').forEach(b=>b.disabled=true);await new Promise(r=>setTimeout(r,260));const q=state.questions[state.index];try{let result;if(state.live){const {data,error}=await state.client.rpc('submit_vote',{p_anonymous_user_id:state.userId,p_question_id:q.id,p_choice:choice});if(error)throw error;result=Array.isArray(data)?data[0]:data}else result=demoResult(q,choice);reveal(q,choice,result)}catch(e){console.error('Vote submission failed',e);ids.choices.classList.remove('is-locked');$$('[data-choice]').forEach(b=>b.disabled=false);ids.errorCard.innerHTML='<strong>Your choice couldn\'t be submitted.</strong><button data-action="retry-vote">TRY AGAIN</button>';ids.errorCard.classList.add('is-visible');ids.errorCard.querySelector('button').onclick=()=>castVote(choice,button)}finally{state.busy=false}}
  function reveal(q,attemptedChoice,r){const choice=r.previous_choice||attemptedChoice;const total=Number(r.total_votes)||0;const pressVotes=Number(r.press_votes)||0;const press=total?Math.round(pressVotes/total*100):50;const walk=100-press;const score=controversy(press);const chosenPct=choice==='PRESS'?press:walk;const isMajority=chosenPct>=50;state.answers.push({q,choice,press,walk,score,agreement:chosenPct,isMinority:chosenPct<50});ids.resultKicker.textContent=r.previous_choice?'YOUR EARLIER CHOICE':'YOUR CHOICE';ids.resultTitle.textContent=choice==='PRESS'?'You pressed it.':'You walked away.';ids.totalVotes.textContent=`${total.toLocaleString()} ${state.live?'real ':''}${total===1?'vote':'votes'}`;ids.positionText.textContent=isMajority?'WITH THE MAJORITY':'WITH THE MINORITY';ids.scoreText.textContent=`${score} · ${controversyLabel(score)}`;ids.neutralNote.textContent=score>=94?'Players are almost perfectly divided.':score>=80?'This question split players closely.':isMajority?'Most players made the same choice.':'Your choice went against the majority.';ids.resultPanel.classList.add('is-visible');requestAnimationFrame(()=>{animateNumber(ids.pressPercent,press);animateNumber(ids.walkPercent,walk);ids.pressBar.style.width=`${press}%`;ids.walkBar.style.width=`${walk}%`});ids.resultPanel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'})}
  function animateNumber(el,target){if(matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=target+'%';return}const start=performance.now(),duration=700;function tick(now){const t=Math.min(1,(now-start)/duration),e=1-Math.pow(1-t,3);el.textContent=Math.round(target*e)+'%';if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}
  function next(){if(state.index>=SESSION_SIZE-1)return finish();const card=$('#dilemmaCard');card.classList.add('is-leaving');setTimeout(()=>{state.index++;renderQuestion();card.classList.remove('is-leaving')},260)}
  function finish(){const a=state.answers;const pressed=a.filter(x=>x.choice==='PRESS').length;const minority=a.filter(x=>x.isMinority).length;const most=[...a].sort((x,y)=>y.score-x.score)[0];const avg=Math.round(a.reduce((n,x)=>n+x.agreement,0)/(a.length||1));$('#pressedStat').innerHTML=`${pressed}<span>/${SESSION_SIZE}</span>`;$('#minorityStat').textContent=minority;$('#topicStat').textContent=most?.q.category||'—';$('#agreementStat').textContent=avg+'%';const counts={};a.forEach(x=>{counts[x.choice==='PRESS'?x.q.press_value:x.q.walk_value]=(counts[x.choice==='PRESS'?x.q.press_value:x.q.walk_value]||0)+1});const leading=Object.entries(counts).sort((x,y)=>y[1]-x[1]).slice(0,2).map(x=>x[0]);$('#profileText').textContent=`Based on this round, your choices leaned toward ${leading[0]||'independent judgement'}${leading[1]?` and ${leading[1].toLowerCase()}`:''}. You agreed with other players ${avg}% of the time on average.`;renderProfile(counts);show('summary')}
  function renderProfile(counts){const axes=[['Freedom','Security'],['Privacy','Convenience'],['Control','Automation'],['Equality','Reward'],['Caution','Progress']];$('#profileBars').innerHTML=axes.map(([l,r])=>{const lv=counts[l]||0,rv=counts[r]||0,pos=lv+rv?Math.round(rv/(lv+rv)*100):50;return`<div class="profile-axis"><div class="axis-labels"><span>${l}</span><span>${r}</span></div><div class="axis-track"><span style="left:${pos}%"></span></div></div>`}).join('')}
  function copyResults(){const text=`I pressed The Button ${state.answers.filter(a=>a.choice==='PRESS').length}/10 times. Minority choices: ${state.answers.filter(a=>a.isMinority).length}. Most divisive topic: ${[...state.answers].sort((a,b)=>b.score-a.score)[0]?.q.category||'—'}.`;navigator.clipboard?.writeText(text).then(()=>{$('#copyStatus').textContent='Results copied — no personal information included.'}).catch(()=>{$('#copyStatus').textContent=text})}
  document.addEventListener('click',e=>{const choice=e.target.closest('[data-choice]');if(choice){castVote(choice.dataset.choice,choice);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'||a==='restart')start();if(a==='next')next();if(a==='home')show('landing');if(a==='retry')start();if(a==='copy')copyResults();if(a==='privacy')$('#privacyDialog').showModal();if(a==='close-dialog')$('#privacyDialog').close()});
  addEventListener('keydown',e=>{if(!screens.game.classList.contains('is-active')||ids.resultPanel.classList.contains('is-visible'))return;if(e.key.toLowerCase()==='p')$('[data-choice="PRESS"]').click();if(e.key.toLowerCase()==='w')$('[data-choice="WALK_AWAY"]').click()});
  if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(console.error));
})();
